input.sparql:
SELECT ?s ?tsid ?node WHERE {
  ?s rdfs:label ?lbl . FILTER(?lbl = "CondPump02")
  ?s ref:hasExternalReference ?ref . 
  ?ref ref:hasTimeseriesId ?tsid .
  OPTIONAL { ?s rdf:type ?node }
}

SELECT ?s ?lbl ?type WHERE {
  ?s rdfs:label ?lbl . FILTER(CONTAINS(LCASE(?lbl), "condpump"))
  OPTIONAL { ?s rdf:type ?type }
}

SELECT ?s ?type ?tsid ?ref WHERE {
  ?s rdfs:label "HeatSys1 Pump" .
  OPTIONAL { ?s rdf:type ?type }
  ?s ref:hasExternalReference ?ref .
  OPTIONAL { ?ref ref:hasTimeseriesId ?tsid }
}
